// Acceptance tests for L2 (the readers). Written by the main thread BEFORE the batch.
// Workers do not edit this file. Contract: docs/arquitectura/03-contratos.md §4.12.
// Roots are created WITHOUT the core (L1): copy of the corpus + an empty state directory.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { makeBareRoot } from '../helpers/fixture.mjs';
import { runEval } from '../../src/eval.js';
import { bundle } from '../../src/readers/cag.js';
import { updateIndex } from '../../src/readers/index.js';
import { openRoot } from '../../src/root.js';
import { search } from '../../src/search.js';

/** @typedef {import('../../src/types.js').Embedder} Embedder */

const NOW = new Date('2026-09-24T12:00:00Z');

/**
 * A deterministic stand-in for a semantic model: texts about the glossary (or the word
 * "terminology", which the corpus never uses) point one way, everything else another.
 * @type {Embedder}
 */
const fakeEmbedder = {
  name: 'fake',
  async embed(texts) {
    return texts.map((t) => (/glossary|terminology/i.test(t) ? [1, 0.1] : [0.1, 1]));
  },
};

test('lexical search finds the section that owns the words (accent- and case-insensitive)', async () => {
  const root = openRoot(makeBareRoot());
  /** @type {Array<[string, string, string]>} */
  const cases = [
    ['rollback procedure', 'manuals/deploy.md', '## Rollback'],
    ['snapshot schedule', 'manuals/backups.md', '## Schedule'],
    ['decision base de datos postgres', 'projects/beta.md', '## Decisión de base de datos'],
    ['vector index before the migration', 'projects/alpha.md', '## Plan'],
    ['quarterly offsite brainstorm', 'inbox/idea.md', ''],
  ];
  for (const [query, rel, key] of cases) {
    const { hits } = await search([root], query, { k: 3, reader: 'lexical', now: NOW });
    assert.equal(hits[0]?.rel, rel, `"${query}" should find ${rel}`);
    assert.equal(hits[0]?.section.key, key, `"${query}" should land on "${key}"`);
  }
});

test('ignored folders and headings inside code fences never show up', async () => {
  const root = openRoot(makeBareRoot());
  const trash = await search([root], 'never be indexed', { reader: 'lexical', now: NOW });
  assert.ok(!trash.hits.some((h) => h.rel.startsWith('.trash/')));
  const fence = await search([root], 'fake heading inside fence', { reader: 'lexical', now: NOW });
  assert.ok(!fence.hits.some((h) => h.section.key === '## Fake heading inside fence'));
});

test('a query with no known words returns nothing', async () => {
  const root = openRoot(makeBareRoot());
  const { hits } = await search([root], 'zyxwv qwertyuiop', { reader: 'lexical', now: NOW });
  assert.equal(hits.length, 0);
});

test('CA-5: expired and superseded notes and sections come out marked', async () => {
  const root = openRoot(makeBareRoot());
  const expired = await search([root], 'temporary pricing offer', { reader: 'lexical', now: NOW });
  assert.equal(expired.hits[0]?.rel, 'notes/expired.md');
  assert.match(expired.hits[0]?.stale?.reason ?? '', /expired/i);

  const old = await search([root], 'old plan migrate without rebuilding', { reader: 'lexical', now: NOW });
  assert.equal(old.hits[0]?.rel, 'notes/old-plan.md');
  assert.match(old.hits[0]?.stale?.reason ?? '', /superseded/i);

  const launch = await search([root], 'launch discount half price', { reader: 'lexical', now: NOW });
  assert.equal(launch.hits[0]?.section.key, '## Launch discount');
  assert.ok(launch.hits[0]?.stale, 'the section with an expired marker is stale');
  const current = await search([root], 'current offer valid all year', { reader: 'lexical', now: NOW });
  assert.equal(current.hits[0]?.section.key, '## Current offer');
  assert.equal(current.hits[0]?.stale, undefined, 'its sibling section is not');
});

test('TE-4: without a reachable embedding service, hybrid degrades to lexical within the timeout and says so', async () => {
  const dir = makeBareRoot({ embeddings: { provider: 'ollama', url: 'http://127.0.0.1:9', timeoutMs: 500 } });
  const root = openRoot(dir);
  const t0 = Date.now();
  const res = await search([root], 'rollback procedure', { reader: 'hybrid', now: NOW });
  assert.ok(Date.now() - t0 < 3000, 'degrades within the timeout');
  assert.equal(typeof res.degraded, 'string');
  assert.ok((res.degraded ?? '').length > 0);
  assert.equal(res.hits[0]?.rel, 'manuals/deploy.md');
});

test('hybrid fuses the lexical and semantic rankings', async () => {
  const root = openRoot(makeBareRoot());
  const lexical = await search([root], 'terminology', { reader: 'lexical', now: NOW });
  assert.equal(lexical.hits.length, 0, 'the corpus never says "terminology"');
  const hybrid = await search([root], 'terminology', { reader: 'hybrid', embedder: fakeEmbedder, now: NOW });
  assert.equal(hybrid.hits[0]?.rel, 'notes/pinned-glossary.md');
  assert.equal(hybrid.degraded, undefined);
});

test('CA-6: both readers return hits of the same shape', async () => {
  const root = openRoot(makeBareRoot());
  for (const reader of /** @type {const} */ (['lexical', 'hybrid'])) {
    const { hits } = await search([root], 'rollback procedure', { reader, embedder: fakeEmbedder, now: NOW });
    const h = hits[0];
    assert.ok(h, `${reader} returned a hit`);
    assert.equal(h.root, root.dir);
    assert.equal(typeof h.rel, 'string');
    assert.ok(Array.isArray(h.section.path));
    assert.equal(typeof h.section.key, 'string');
    assert.equal(typeof h.section.start, 'number');
    assert.equal(typeof h.section.end, 'number');
    assert.equal(typeof h.score, 'number');
    assert.equal(typeof h.text, 'string');
    assert.ok(h.text.length <= 1200);
  }
});

test('D-P5: one search spans several roots and says which root each hit came from', async () => {
  const one = openRoot(makeBareRoot());
  const twoDir = makeBareRoot();
  fs.writeFileSync(path.join(twoDir, 'only-here.md'), '# Only here\n\nThe zebra crossing inventory lives in the second root.\n');
  const two = openRoot(twoDir);
  const { hits } = await search([one, two], 'zebra crossing inventory', { reader: 'lexical', now: NOW });
  assert.equal(hits[0]?.rel, 'only-here.md');
  assert.equal(hits[0]?.root, two.dir);
  const both = await search([one, two], 'rollback procedure', { reader: 'lexical', k: 5, now: NOW });
  assert.ok(both.hits.some((h) => h.root === one.dir) && both.hits.some((h) => h.root === two.dir));
});

test('CA-6: the CAG bundle is deterministic, bounded, pinned first, and marks stale notes', () => {
  const root = openRoot(makeBareRoot());
  const b1 = bundle(root, { budget: 4000, now: NOW });
  const b2 = bundle(root, { budget: 4000, now: NOW });
  assert.equal(b1, b2, 'same root, same bytes');
  assert.ok(Buffer.byteLength(b1, 'utf8') <= 4000);
  assert.ok(b1.indexOf('# Glossary') !== -1 && b1.indexOf('# Glossary') < b1.indexOf('- manuals/'), 'pinned notes come first');
  assert.match(b1, /notes\/expired\.md.*\[STALE:/);
  const laterSameDay = bundle(root, { budget: 4000, now: new Date('2026-09-24T23:59:00Z') });
  assert.equal(laterSameDay, b1, 'the bundle only depends on the UTC day of now, never the time');
  const small = bundle(root, { budget: 300, now: NOW });
  assert.ok(Buffer.byteLength(small, 'utf8') <= 300);
  assert.match(small, /notes omitted \(budget 300 bytes\)\s*$/);
});

test('the index updates incrementally', async () => {
  const root = openRoot(makeBareRoot());
  const first = await updateIndex(root);
  assert.equal(first.reindexed, first.total);
  assert.ok(first.total >= 10);
  const second = await updateIndex(root);
  assert.equal(second.reindexed, 0);
  fs.appendFileSync(path.join(root.dir, 'manuals/deploy.md'), '\nOne more line.\n');
  const third = await updateIndex(root);
  assert.equal(third.reindexed, 1);
});

test('eval reports hits per kind of case', async () => {
  const root = openRoot(makeBareRoot());
  const report = await runEval(
    [root],
    [
      { query: 'rollback procedure', want: ['manuals/deploy'] },
      { query: 'snapshot schedule', want: ['manuals/backups'], wantText: 'thirty daily snapshots' },
      { query: 'zyxwv qwertyuiop', none: true },
    ],
    { k: 3 },
  );
  assert.deepEqual(report.note, { hit: 2, total: 2 });
  assert.deepEqual(report.section, { hit: 1, total: 1 });
  assert.deepEqual(report.none, { hit: 1, total: 1 });
  assert.equal(report.failures.length, 0);
});

// ── Added by the main thread after wave 1, from the worker's objections ─────

test('TE-4 (slow, not refused): an embedder that never answers is abandoned within the timeout', async () => {
  const root = openRoot(makeBareRoot({ embeddings: { provider: 'ollama', timeoutMs: 300 } }));
  /** @type {Embedder} */
  const hanging = { name: 'hanging', embed: () => new Promise(() => {}) };
  const t0 = Date.now();
  const res = await search([root], 'rollback procedure', { reader: 'hybrid', embedder: hanging, now: NOW });
  assert.ok(Date.now() - t0 < 2500, `took ${Date.now() - t0} ms`);
  assert.ok((res.degraded ?? '').length > 0);
  assert.equal(res.hits[0]?.rel, 'manuals/deploy.md');
});

test('CA-6: the CAG bundle never goes over any budget (swept)', () => {
  const root = openRoot(makeBareRoot());
  for (let budget = 200; budget <= 4000; budget += 37) {
    const b = bundle(root, { budget, now: NOW });
    assert.ok(Buffer.byteLength(b, 'utf8') <= budget, `budget ${budget}: got ${Buffer.byteLength(b, 'utf8')} bytes`);
  }
});
